import path from 'node:path';
import { realpath } from 'node:fs/promises';

/**
 * Resolve a relative path below the workspace root and return the absolute result.
 * If the value is an absolute path, or escapes the root via ../, throw an Error
 * whose message contains the word "escapes".
 * Uses path.relative rather than string-prefix checks.
 */
export async function resolveRelative(root, value) {
  const rootReal = await realpath(root);
  const input = String(value || '.');

  // Reject absolute paths
  if (path.isAbsolute(input)) {
    throw new Error(`Path escapes the workspace: ${input}`);
  }

  // Resolve the target path
  const target = path.resolve(rootReal, input);

  // Use path.relative to check if the target escapes the root
  const relative = path.relative(rootReal, target);
  if (relative.startsWith('..' + path.sep) || relative === '..' || path.isAbsolute(relative)) {
    throw new Error(`Path escapes the workspace: ${input}`);
  }

  return target;
}
